if (
  baseline === undefined ||
  stored.value.raw !== baseline ||
  document.revision !== expectedRevision ||
  this.current?.revision !== expectedRevision ||
  stored.value.document.revision !== expectedRevision
)
  return failure('conflict', 'Preferences changed elsewhere. Reload before saving.');

this.table.apply(state, image ?? undefined);
if (this.disposed) return failure('disposed', 'The table is closed.');
if (this.settled === 'table' && !this.transitioning) {
  const activated = this.activate(true);
  if (!activated.ok) return activated;
}
if (this.disposed) return this.unavailable();
